const i="—",m=" ";function u(t,n){return t.toLocaleString("fr-FR",n).replace(/[  ]/g," ")}function e(t){if(t==null||t==="")return!0;const n=Number(t);return!Number.isFinite(n)}function N(t,n=2){return e(t)?i:u(Number(t),{minimumFractionDigits:n,maximumFractionDigits:n})}function $(t){return e(t)?i:u(Math.round(Number(t)))}function g(t,n="EUR",r=2){return e(t)?i:u(Number(t),{style:"currency",currency:n,minimumFractionDigits:r,maximumFractionDigits:r})}function d(t,n="EUR"){return g(t,n,0)}function x(t){return e(t)?i:`${u(Number(t))}${m}%`}function b(t,n=2){return e(t)?i:`${u(Number(t),{minimumFractionDigits:n,maximumFractionDigits:n})}${m}%`}function E(t,n=2){return e(t)?i:b(Number(t)*100,n)}function R(t,n=4){if(e(t))return i;const r=Number(t);return r!==0&&Math.abs(r)<1e-4?u(r,{notation:"scientific",maximumFractionDigits:2}):u(r,{minimumFractionDigits:n,maximumFractionDigits:n})}function y(t,n=1){return e(t)?i:`${N(t,n)}${m}bps`}function o(t){return String(t).padStart(2,"0")}const D=/^(\d{4})-(\d{2})-(\d{2})$/;function f(t){if(!t)return null;if(t instanceof Date)return Number.isNaN(t.getTime())?null:t;const n=D.exec(t);if(n){const[,a,c,s]=n;return new Date(Number(a),Number(c)-1,Number(s))}const r=new Date(t);return Number.isNaN(r.getTime())?null:r}function F(t){const n=f(t);return n?`${o(n.getDate())}/${o(n.getMonth()+1)}/${n.getFullYear()}`:i}function M(t){const n=f(t);return n?`${F(n)} ${o(n.getHours())}:${o(n.getMinutes())}`:i}export{b as a,N as b,$ as c,d,R as e,F as f,M as g,y as h,E as i,x as j};
